/* eslint-disable space-in-parens */

/// <reference types="@stdlib/types"/>

import zeros = require( '@stdlib/ndarray/zeros' );
import mskmax = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const mask = zeros( [ 2, 2 ], {
		'dtype': 'uint8'
	});

	mskmax<number, number>( x, mask ); // $ExpectType OutputArray<number>
	mskmax<number, number>( x, mask, {} ); // $ExpectType OutputArray<number>
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	const mask = zeros( [ 2, 2 ], {
		'dtype': 'uint8'
	});

	mskmax( '5', mask ); // $ExpectError
	mskmax( 5, mask ); // $ExpectError
	mskmax( true, mask ); // $ExpectError
	mskmax( false, mask ); // $ExpectError
	mskmax( null, mask ); // $ExpectError
	mskmax( void 0, mask ); // $ExpectError
	mskmax( {}, mask ); // $ExpectError
	mskmax( ( x: number ): number => x, mask ); // $ExpectError

	mskmax( '5', mask, {} ); // $ExpectError
	mskmax( 5, mask, {} ); // $ExpectError
	mskmax( true, mask, {} ); // $ExpectError
	mskmax( false, mask, {} ); // $ExpectError
	mskmax( null, mask, {} ); // $ExpectError
	mskmax( void 0, mask, {} ); // $ExpectError
	mskmax( {}, mask, {} ); // $ExpectError
	mskmax( ( x: number ): number => x, mask, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not an ndarray...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	mskmax( x, '5' ); // $ExpectError
	mskmax( x, 5 ); // $ExpectError
	mskmax( x, true ); // $ExpectError
	mskmax( x, false ); // $ExpectError
	mskmax( x, null ); // $ExpectError
	mskmax( x, void 0 ); // $ExpectError
	mskmax( x, ( x: number ): number => x ); // $ExpectError

	mskmax( x, '5', {} ); // $ExpectError
	mskmax( x, 5, {} ); // $ExpectError
	mskmax( x, true, {} ); // $ExpectError
	mskmax( x, false, {} ); // $ExpectError
	mskmax( x, null, {} ); // $ExpectError
	mskmax( x, void 0, {} ); // $ExpectError
	mskmax( x, ( x: number ): number => x, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not an object...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const mask = zeros( [ 2, 2 ], {
		'dtype': 'uint8'
	});

	mskmax( x, mask, '5' ); // $ExpectError
	mskmax( x, mask, 5 ); // $ExpectError
	mskmax( x, mask, true ); // $ExpectError
	mskmax( x, mask, false ); // $ExpectError
	mskmax( x, mask, null ); // $ExpectError
	mskmax( x, mask, [] ); // $ExpectError
	mskmax( x, mask, ( x: number ): number => x ); // $ExpectError
}

