// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const mask = zeros( [ 2, 2 ], {
		'dtype': 'uint8'
	});

	mskmax(); // $ExpectError
	mskmax( x ); // $ExpectError
	mskmax( x, mask, {}, {} ); // $ExpectError
}

// Attached to the function is an `assign` method which returns an ndarray...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const mask = zeros( [ 2, 2 ], {
		'dtype': 'uint8'
	});
	const out = zeros( [], {
		'dtype': 'float64'
	});

	mskmax.assign( x, mask, out ); // $ExpectType float64ndarray
	mskmax.assign( x, mask, out, {} ); // $ExpectType float64ndarray
}

// The compiler throws an error if the `assign` method is provided a first argument which is not an ndarray...
{
	const mask = zeros( [ 2, 2 ], {
		'dtype': 'uint8'
	});
	const out = zeros( [], {
		'dtype': 'float64'
	});

	mskmax.assign( '5', mask, out ); // $ExpectError
	mskmax.assign( 5, mask, out ); // $ExpectError
	mskmax.assign( true, mask, out ); // $ExpectError
	mskmax.assign( false, mask, out ); // $ExpectError
	mskmax.assign( null, mask, out ); // $ExpectError
	mskmax.assign( void 0, mask, out ); // $ExpectError
	mskmax.assign( {}, mask, out ); // $ExpectError
	mskmax.assign( ( x: number ): number => x, mask, out ); // $ExpectError

	mskmax.assign( '5', mask, out, {} ); // $ExpectError
	mskmax.assign( 5, mask, out, {} ); // $ExpectError
	mskmax.assign( true, mask, out, {} ); // $ExpectError
	mskmax.assign( false, mask, out, {} ); // $ExpectError
	mskmax.assign( null, mask, out, {} ); // $ExpectError
	mskmax.assign( void 0, mask, out, {} ); // $ExpectError
	mskmax.assign( {}, mask, out, {} ); // $ExpectError
	mskmax.assign( ( x: number ): number => x, mask, out, {} ); // $ExpectError
}

